def run_calc(expr):
    return eval(expr)

print(run_calc(input('enter expression: ')))

output:
**Issue:** eval() executes arbitrary code supplied by the user.
**Why:** `expr` can be `__import__('os').system('rm -rf /')`, giving the attacker a shell.
**Fix:**
def run_calc(expr):
    import ast, operator
    ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    def ev(node):
        if isinstance(node, ast.Expression): return ev(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)): return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in ops: return ops[type(node.op)](ev(node.left), ev(node.right))
        raise ValueError('unsupported expression')
    return ev(ast.parse(expr, mode='eval'))

